"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["अदना और तारसूस: रूपेनी रियासत किलिकिया आर्मेनियाई राज्य में बदली", "de3c4beb"], "d": ["अदना और तारसूस को थामे रूपेनी राजवंश ने राजा की उपाधि पाई; यह उसी राजवंश की उपाधि का परिवर्तन है, भूमि ने हाथ नहीं बदला। राज्याभिषेक का दिन TDV में नहीं मिला — तिथि किलिकिया आर्मेनियाई राज्य के राजवंश-परिचय के आरंभ से ली गई (राजवंश-परिचय का दिन स्रोत नहीं है)।", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["ट्रैबज़ोन रूमी साम्राज्य स्थापित हुआ — गिरेसुन और सिनोप भी सीमाओं में", "a99b6ba0"], "d": ["इस्तांबुल के लातिनों द्वारा लिए जाने पर ट्रैबज़ोन भागे आलेक्सियोस कोम्नेनोस ने स्वयं को सम्राट घोषित किया; नगर नए राज्य का केंद्र बना। कोम्नेनोस पौत्रों आलेक्सियोस और दाविद द्वारा स्थापित राज्य सिनोप तक फैला; गिरेसुन भी ट्रैबज़ोन रूमी साम्राज्य की सीमाओं के भीतर रहा।", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["कुताहिया इज़निक (लास्कारिस) साम्राज्य के आधिपत्य में — स्रोत में तिथियुक्त साक्ष्य", "d91fa405"], "d": ["स्रोत कुताहिया नगर को इस तिथि को इज़निक (लास्कारिस) साम्राज्य के शासन में दर्शाता है; इससे पहले का स्वामित्व स्रोत में तिथियुक्त नहीं है (एटलस इस तिथि से पहले का भाग रिक्त छोड़ता है)।", "50f100b1"]},
